#include "containers.h"
#ifndef CD_MUTANT
#define CD_MUTANT 0
#endif
static int hash_valid(const struct cd_hash*h){return h&&h->slots&&h->capacity&&h->capacity<=16&&h->live<=h->occupied&&h->occupied<=h->capacity&&h->allocator.take&&h->allocator.release;}
static unsigned start(const struct cd_hash*h,uint32_t key){return h->clustered?0:key%h->capacity;}
static int locate(const struct cd_hash*h,uint32_t key,unsigned*empty,unsigned*probes){*empty=h->capacity;*probes=0;unsigned at=start(h,key);for(unsigned i=0;i<h->capacity;++i){++*probes;const struct cd_bucket*b=&h->slots[at];if(b->state==1&&b->key==key)return(int)at;if(b->state!=1&&*empty==h->capacity)*empty=at;if(b->state==0||(CD_MUTANT==6&&b->state==2))break;if(++at==h->capacity)at=0;}return -1;}
enum cd_status cd_hash_init(struct cd_hash*h,unsigned cap,struct cd_hash_allocator allocator,unsigned cluster){if(!h||!cap||cap>16||!allocator.take||!allocator.release)return CD_INVALID;struct cd_bucket*p=allocator.take(allocator.context,cap);if(!p)return CD_NOMEM;for(unsigned i=0;i<cap;++i)p[i]=(struct cd_bucket){0,0,0};*h=(struct cd_hash){p,cap,0,0,cluster!=0,allocator};return CD_OK;}
enum cd_status cd_hash_put(struct cd_hash*h,uint32_t key,int value,unsigned*probes){if(!hash_valid(h)||!probes)return CD_INVALID;unsigned empty;int at=locate(h,key,&empty,probes);if(at<0){if(empty==h->capacity)return CD_FULL;at=(int)empty;if(h->slots[at].state==0)++h->occupied;++h->live;}h->slots[at]=(struct cd_bucket){key,value,1};return CD_OK;}
enum cd_status cd_hash_get(const struct cd_hash*h,uint32_t key,int*out,unsigned*probes){if(!hash_valid(h)||!out||!probes)return CD_INVALID;unsigned empty;int at=locate(h,key,&empty,probes);if(at<0)return CD_MISSING;*out=h->slots[at].value;return CD_OK;}
enum cd_status cd_hash_delete(struct cd_hash*h,uint32_t key){if(!hash_valid(h))return CD_INVALID;unsigned empty,probes;int at=locate(h,key,&empty,&probes);if(at<0)return CD_MISSING;h->slots[at].state=2;--h->live;return CD_OK;}
enum cd_status cd_hash_rebuild(struct cd_hash*h,unsigned cap){if(!hash_valid(h)||cap<h->live||!cap||cap>16)return CD_INVALID;struct cd_hash replacement;enum cd_status result=cd_hash_init(&replacement,cap,h->allocator,h->clustered);if(result!=CD_OK)return result;for(unsigned i=0;i<h->capacity;++i)if(h->slots[i].state==1){unsigned probes;cd_hash_put(&replacement,h->slots[i].key,h->slots[i].value,&probes);}struct cd_bucket*old=h->slots;*h=replacement;h->allocator.release(h->allocator.context,old);return CD_OK;}
enum cd_status cd_hash_destroy(struct cd_hash*h){if(!hash_valid(h))return CD_INVALID;struct cd_bucket*old=h->slots;h->slots=0;h->capacity=h->live=h->occupied=0;h->allocator.release(h->allocator.context,old);return CD_OK;}
static unsigned key_hash(const unsigned char*p,size_t n){unsigned h=0;for(size_t i=0;i<n;++i)h=(h*33u+p[i])%4;return h;}
static int equal(const struct cd_key*k,const unsigned char*p,size_t n){if(k->length!=n)return 0;for(size_t i=0;i<n;++i)if(k->bytes[i]!=p[i])return 0;return 1;}
enum cd_status cd_bytemap_put(struct cd_byte_map*m,const unsigned char*p,size_t n,int value){if(!m||(!p&&n)||n>8)return CD_INVALID;unsigned at=key_hash(p,n);for(unsigned i=0;i<4;++i){struct cd_key*k=&m->keys[at];if(!m->live[at]||equal(k,p,n)){for(size_t j=0;j<n;++j)k->bytes[j]=p[j];k->length=n;k->value=value;m->live[at]=1;return CD_OK;}at=(at+1)%4;}return CD_FULL;}
enum cd_status cd_bytemap_get(const struct cd_byte_map*m,const unsigned char*p,size_t n,int*out){if(!m||!out||(!p&&n)||n>8)return CD_INVALID;unsigned at=key_hash(p,n);for(unsigned i=0;i<4;++i){if(!m->live[at])return CD_MISSING;if(equal(&m->keys[at],p,n)){*out=m->keys[at].value;return CD_OK;}at=(at+1)%4;}return CD_MISSING;}
void cd_trie_init(struct cd_trie*t){for(unsigned i=0;i<64;++i)t->nodes[i]=(struct cd_trie_node){-1,-1,-1,0,0,0};t->nodes[0].live=1;t->generation=1;t->count=1;}
static int child(const struct cd_trie*t,int parent,unsigned char byte){int at=t->nodes[parent].child;while(at>=0&&t->nodes[at].byte!=byte)at=t->nodes[at].sibling;return at;}
static int path(const struct cd_trie*t,const unsigned char*p,size_t n){int at=0;for(size_t i=0;i<n&&at>=0;++i)at=child(t,at,p[i]);return at;}
enum cd_status cd_trie_insert(struct cd_trie*t,const unsigned char*p,size_t n,unsigned fail){if(!t||(!p&&n)||n>8||!t->generation)return CD_INVALID;int parent=0;size_t matched=0;while(matched<n){int next=child(t,parent,p[matched]);if(next<0)break;parent=next;++matched;}if(matched==n&&t->nodes[parent].terminal)return CD_DUPLICATE;if(t->generation==UINT32_MAX)return CD_FULL;unsigned needed=(unsigned)(n-matched),slots[8],made=0;for(unsigned i=1;i<64&&made<needed;++i)if(!t->nodes[i].live){if(fail==made+1)return CD_NOMEM;slots[made++]=i;}if(made!=needed)return CD_FULL;for(unsigned i=0;i<needed;++i){unsigned at=slots[i];t->nodes[at]=(struct cd_trie_node){parent,-1,t->nodes[parent].child,p[matched+i],1,0};t->nodes[parent].child=(int)at;parent=(int)at;}t->nodes[parent].terminal=1;t->count+=needed;++t->generation;return CD_OK;}
enum cd_status cd_trie_delete(struct cd_trie*t,const unsigned char*p,size_t n){if(!t||(!p&&n)||n>8)return CD_INVALID;int at=path(t,p,n);if(at<0||!t->nodes[at].terminal)return CD_MISSING;if(t->generation==UINT32_MAX)return CD_FULL;t->nodes[at].terminal=0;while(at&&t->nodes[at].child<0&&!t->nodes[at].terminal){int parent=t->nodes[at].parent,*edge=&t->nodes[parent].child;while(*edge!=at)edge=&t->nodes[*edge].sibling;*edge=t->nodes[at].sibling;t->nodes[at].live=0;--t->count;at=parent;}++t->generation;return CD_OK;}
static int descendant(const struct cd_trie*t,int at,int root){while(at>=0){if(at==root)return 1;at=t->nodes[at].parent;}return 0;}
enum cd_status cd_trie_prefix(const struct cd_trie*t,const unsigned char*p,size_t n,struct cd_trie_cursor*out){if(!t||!out||(!p&&n)||n>8)return CD_INVALID;int root=path(t,p,n);if(root<0)return CD_MISSING;struct cd_trie_cursor cursor={t,t->generation,{0},0,0};for(unsigned i=0;i<64;++i)if(t->nodes[i].live&&t->nodes[i].terminal&&descendant(t,(int)i,root))cursor.nodes[cursor.count++]=i;*out=cursor;return CD_OK;}
enum cd_status cd_trie_next(struct cd_trie_cursor*c,struct cd_key*out){if(!c||!out||!c->owner)return CD_INVALID;if(c->generation!=c->owner->generation&&CD_MUTANT!=7)return CD_BUSY;if(c->position==c->count)return CD_EMPTY;unsigned char reverse[8];size_t n=0;int at=(int)c->nodes[c->position];while(at){if(n==8)return CD_INVALID;reverse[n++]=c->owner->nodes[at].byte;at=c->owner->nodes[at].parent;}struct cd_key key={{0},n,0};for(size_t i=0;i<n;++i)key.bytes[i]=reverse[n-1-i];*out=key;++c->position;return CD_OK;}
void cd_sparse_init(struct cd_sparse*s){s->count=0;s->generation=1;for(unsigned i=0;i<32;++i)s->tags[i]=s->sparse[i]=0;}
int cd_sparse_has(const struct cd_sparse*s,unsigned key){return s&&key<32&&s->tags[key]==s->generation&&s->sparse[key]<s->count&&s->dense[s->sparse[key]]==key;}
enum cd_status cd_sparse_insert(struct cd_sparse*s,unsigned key){if(!s||key>=32)return CD_INVALID;if(cd_sparse_has(s,key))return CD_DUPLICATE;if(s->count==16)return CD_FULL;s->sparse[key]=s->count;s->tags[key]=s->generation;s->dense[s->count++]=key;return CD_OK;}
enum cd_status cd_sparse_remove(struct cd_sparse*s,unsigned key){if(!s||key>=32)return CD_INVALID;if(!cd_sparse_has(s,key))return CD_MISSING;unsigned at=s->sparse[key],last=s->dense[--s->count];s->dense[at]=last;s->sparse[last]=at;s->tags[key]=0;return CD_OK;}
void cd_sparse_clear(struct cd_sparse*s){s->count=0;if(s->generation==3){for(unsigned i=0;i<32;++i)s->tags[i]=0;s->generation=1;}else ++s->generation;}
enum cd_status cd_sets_init(struct cd_sets*s,unsigned n){if(!s||n>16)return CD_INVALID;s->count=n;s->used=0;for(unsigned i=0;i<n;++i){s->parent[i]=i;s->size[i]=1;}return CD_OK;}
static unsigned root(unsigned*p,unsigned at){unsigned r=at;while(p[r]!=r)r=p[r];while(p[at]!=at){unsigned next=p[at];p[at]=r;at=next;}return r;}
static enum cd_status commit(struct cd_sets*s,const unsigned*p,const unsigned*size){size_t required=0;for(unsigned i=0;i<s->count;++i)required+=(p[i]!=s->parent[i])+(size[i]!=s->size[i]);if(required>128-s->used)return CD_FULL;for(unsigned i=0;i<s->count;++i){if(p[i]!=s->parent[i]){s->log[s->used++]=(struct cd_undo){0,i,s->parent[i]};s->parent[i]=p[i];}if(size[i]!=s->size[i]){s->log[s->used++]=(struct cd_undo){1,i,s->size[i]};s->size[i]=size[i];}}return CD_OK;}
enum cd_status cd_sets_find(struct cd_sets*s,unsigned at,unsigned*out){if(!s||!out||at>=s->count||s->used>128)return CD_INVALID;unsigned p[16],sizes[16];for(unsigned i=0;i<s->count;++i){p[i]=s->parent[i];sizes[i]=s->size[i];}unsigned r=root(p,at);enum cd_status status=commit(s,p,sizes);if(status==CD_OK)*out=r;return status;}
enum cd_status cd_sets_union(struct cd_sets*s,unsigned a,unsigned b){if(!s||a>=s->count||b>=s->count||s->used>128)return CD_INVALID;unsigned p[16],sizes[16];for(unsigned i=0;i<s->count;++i){p[i]=s->parent[i];sizes[i]=s->size[i];}unsigned x=root(p,a),y=root(p,b);if(x!=y){if(sizes[x]<sizes[y]){unsigned swap=x;x=y;y=swap;}p[y]=x;sizes[x]+=sizes[y];}return commit(s,p,sizes);}
enum cd_status cd_sets_rollback(struct cd_sets*s,size_t mark){if(!s||mark>s->used)return CD_INVALID;while(s->used>mark){struct cd_undo change=s->log[--s->used];if(change.field)s->size[change.index]=change.old;else s->parent[change.index]=change.old;}return CD_OK;}
enum cd_status cd_csr_build(struct cd_csr*out,unsigned vertices,const struct cd_edge*edges,size_t n,unsigned parallel){if(!out||vertices>8||n>32||(!edges&&n)||parallel>1)return CD_INVALID;struct cd_csr result={vertices,(unsigned)n,{0},{{0}}};for(size_t i=0;i<n;++i){if(edges[i].from>=vertices||edges[i].to>=vertices)return CD_INVALID;if(!parallel)for(size_t j=0;j<i;++j)if(edges[j].from==edges[i].from&&edges[j].to==edges[i].to)return CD_DUPLICATE;++result.offset[edges[i].from+1];}for(unsigned i=1;i<=vertices;++i)result.offset[i]+=result.offset[i-1];unsigned next[8];for(unsigned i=0;i<vertices;++i)next[i]=result.offset[i];for(size_t i=0;i<n;++i)result.edges[next[edges[i].from]++]=edges[i];*out=result;return CD_OK;}
enum cd_status cd_filter_insert(unsigned char*bits,unsigned key){if(!bits||key>=16)return CD_INVALID;*bits|=(unsigned char)((1u<<(key%8))|(1u<<((3*key+1)%8)));return CD_OK;}
enum cd_status cd_filter_query(unsigned char bits,unsigned key,unsigned*out){if(!out||key>=16)return CD_INVALID;unsigned mask=(1u<<(key%8))|(1u<<((3*key+1)%8));*out=(bits&mask)==mask;return CD_OK;}
enum cd_status cd_counting_insert(struct cd_counting_filter*f,unsigned key){if(!f||key>=16)return CD_INVALID;unsigned a=key%8,b=(3*key+1)%8;if(f->cells[a]==3||f->cells[b]==3||f->keys[key]==3)return CD_FULL;++f->cells[a];++f->cells[b];++f->keys[key];return CD_OK;}
enum cd_status cd_counting_delete(struct cd_counting_filter*f,unsigned key){if(!f||key>=16)return CD_INVALID;if(!f->keys[key])return CD_MISSING;--f->cells[key%8];--f->cells[(3*key+1)%8];--f->keys[key];return CD_OK;}
void cd_chain_init(struct cd_chain*c){c->count=0;for(unsigned i=0;i<4;++i)c->head[i]=-1;for(unsigned i=0;i<16;++i)c->nodes[i]=(struct cd_chain_node){0,0,-1,0};}
enum cd_status cd_chain_put(struct cd_chain*c,uint32_t key,int value){if(!c)return CD_INVALID;unsigned bucket=key%4;for(int i=c->head[bucket];i>=0;i=c->nodes[i].next)if(c->nodes[i].key==key){c->nodes[i].value=value;return CD_OK;}unsigned free_slot=0;while(free_slot<16&&c->nodes[free_slot].live)++free_slot;if(free_slot==16)return CD_FULL;c->nodes[free_slot]=(struct cd_chain_node){key,value,c->head[bucket],1};c->head[bucket]=(int)free_slot;++c->count;return CD_OK;}
enum cd_status cd_chain_get(const struct cd_chain*c,uint32_t key,int*out,unsigned*probes){if(!c||!out||!probes)return CD_INVALID;*probes=0;for(int i=c->head[key%4];i>=0;i=c->nodes[i].next){++*probes;if(c->nodes[i].key==key){*out=c->nodes[i].value;return CD_OK;}}return CD_MISSING;}
enum cd_status cd_chain_delete(struct cd_chain*c,uint32_t key){if(!c)return CD_INVALID;int*edge=&c->head[key%4];while(*edge>=0){struct cd_chain_node*n=&c->nodes[*edge];if(n->key==key){*edge=n->next;n->live=0;n->next=-1;--c->count;return CD_OK;}edge=&n->next;}return CD_MISSING;}
enum cd_status cd_bitset_mask(unsigned universe,uint32_t*out){if(!out||universe>32)return CD_INVALID;*out=universe==32?UINT32_MAX:((UINT32_C(1)<<universe)-1);return CD_OK;}
enum cd_status cd_bitset_algebra(uint32_t a,uint32_t b,unsigned universe,uint32_t*join,uint32_t*meet,uint32_t*difference){uint32_t mask;if(!join||!meet||!difference||cd_bitset_mask(universe,&mask)!=CD_OK)return CD_INVALID;*join=(a|b)&mask;*meet=(a&b)&mask;*difference=(a&~b)&mask;return CD_OK;}
enum cd_status cd_bitset_next(uint32_t bits,unsigned universe,unsigned*position,unsigned*out){if(!position||!out||universe>32||*position>universe)return CD_INVALID;unsigned at=*position;while(at<universe&&!(bits&(UINT32_C(1)<<at)))++at;if(at==universe){*position=at;return CD_EMPTY;}*out=at;*position=at+1;return CD_OK;}
